function esc(s){return String(s==null?'':s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');}
// Postgres composite address cast to text looks like ("PO Box 7066",,,,"San Juan",PR,00916-7066,)
// -> split top-level, unquote, drop empty parts, join with commas for a clean address line.
function fmtAddr(raw){
  if(raw==null||raw==='') return '';
  var s=String(raw).trim();
  if(s.charAt(0)==='(' && s.charAt(s.length-1)===')') s=s.slice(1,-1);
  var parts=[],cur='',q=false;
  for(var i=0;i<s.length;i++){var c=s.charAt(i);
    if(c==='"'){ if(q && s.charAt(i+1)==='"'){cur+='"';i++;} else {q=!q;} }
    else if(c===',' && !q){ parts.push(cur); cur=''; }
    else { cur+=c; } }
  parts.push(cur);
  parts=parts.map(function(p){return p.trim();}).filter(function(p){return p!=='';});
  return parts.join(', ');
}
function vv(val){return (val===''||val==null)?'<span class="na">N/A</span>':esc(val);}
function item(label,val){return '<div class="item"><span class="lbl">'+esc(label)+':</span> <span class="val">'+vv(val)+'</span></div>';}
function line(label,val){return '<div class="line"><span class="lbl">'+esc(label)+':</span> <span class="val">'+vv(val)+'</span></div>';}
function render(model){
  var h=(model&&model.header)||{};
  var ps=(model&&Array.isArray(model.providers))?model.providers:[];
  var root=document.getElementById('root'); if(!root) return;
  var html='<div class="hd">General Information</div>'
    +'<div class="section">'+line('ID',h.id)+line('Vendor Code',h.code)+line('Vendor Name',h.pretty_name)+'</div>';
  if(!ps.length){ html+='<div class="box"><div class="empty">No provider mappings on file for this vendor.</div></div>'; }
  ps.forEach(function(p){
    html+='<div class="box"><div class="toprow">'
      +item('Provider',p.provider)+item('Provider ID',p.provider_id)
      +'<div class="item"><span class="globe">\uD83C\uDF10</span><span class="val">'+vv(p.web_address)+'</span></div>'
      +'</div><div class="grid">'
      +item('Vendor Name',p.name)+item('Vendor Code',p.code)+item('Remittance Name',p.remittance_name)
      +item('Main Phone',p.main_phone)+item('Customer Service Phone',p.custsvc_phone)+item('Remittance Address',fmtAddr(p.remittance_address))
      +item('Priority Phone',p.priority_phone)+item('Emergency Phone',p.emergency_phone)
      +'</div></div>';
  });
  root.innerHTML=html;
}
appsmith.onReady(function(){ render(appsmith.model); appsmith.onModelChange(render); });

